using PhotoTrail.Windows;
using System.Text.Json;

static class TrackAdjustmentChecks
{
 public static async Task RunAsync()
 {
  string root=Environment.GetEnvironmentVariable("PHOTOTRAIL_TEST_OUTPUT")??throw new Exception("Set isolated output");string folder=Path.Combine(root,"track-core-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
  int passed=0;void Check(bool value,string name){if(!value)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
  async Task Reject(Func<Task> action,string name){try{await action();}catch(Exception e)when(e is ArgumentException or IOException or InvalidDataException or JsonException or OperationCanceledException){Check(true,name);return;}throw new Exception(name);}
  TrackData Make(double latitude=0,double longitude=0)=>new(new IReadOnlyList<TrackPoint>[] {new TrackPoint[]{new(longitude,latitude,12,DateTimeOffset.UnixEpoch.AddSeconds(1700000000).AddMilliseconds(125)),new(longitude+0.0001,latitude,null,null)},new TrackPoint[]{new(longitude,latitude,13,DateTimeOffset.UnixEpoch.AddSeconds(1700000010).AddMilliseconds(125))}});
  var original=Make();Check(TrackAdjustment.Equal(original,TrackAdjustment.Adjust(original,0,0,0)),"zero-identity");
  var negative=TrackAdjustment.Adjust(original,-3600.5,0,0);Check(negative.Segments[0][0].Time==DateTimeOffset.UnixEpoch.AddSeconds(1699996399).AddMilliseconds(625),"negative-fraction-time");Check(negative.Segments[0][1].Time is null&&negative.Segments[0][0].Elevation==12&&negative.Segments[1][0].Time-negative.Segments[0][0].Time==TimeSpan.FromSeconds(10),"segments-order-elevation-interval-missing-time");
  var north=TrackAdjustment.Adjust(original,0,0,100);double latitudeError=Math.Abs(north.Segments[0][0].Latitude-0.000899320363724538);Check(latitudeError<=1e-10&&Math.Abs(north.Segments[0][0].Longitude)<=1e-10,"common-north-coordinate-tolerance");
  double timeError=Math.Abs((negative.Segments[0][0].Time!.Value-DateTimeOffset.UnixEpoch).TotalSeconds-1699996399.625);Check(timeError<=1e-6,"common-time-tolerance");
  using(var common=JsonDocument.Parse(File.ReadAllText(Environment.GetEnvironmentVariable("PHOTOTRAIL_TRACK_CONTRACT_FIXTURE")!))){Check(common.RootElement.GetProperty("trackAdjustment").GetProperty("radiusMeters").GetDouble()==6371008.8,"fixed-shared-contract-read");var cases=common.RootElement.GetProperty("cases");Check(cases[0].GetProperty("expected").GetProperty("latitude").GetDouble()==0.000899320363724538&&cases[1].GetProperty("expected").GetProperty("epoch").GetDouble()==1699996399.625,"fixed-common-cases-correspond");}
  var untimed=new TrackData(new[]{(IReadOnlyList<TrackPoint>)new[]{new TrackPoint(0,0,null,null)}});Check(TrackAdjustment.Adjust(untimed,0,-100,-100).Segments[0][0].Time is null,"wholly-untimed-space-allowed");await Reject(()=>{TrackAdjustment.Adjust(untimed,1,0,0);return Task.CompletedTask;},"wholly-untimed-nonzero-time-rejected");
  var crossing=TrackAdjustment.Adjust(Make(longitude:179.999),0,1000,0);Check(crossing.Segments[0][0].Longitude< -179.99,"dateline-normalized");
  foreach(var(east,northMeters)in new[]{(100d,100d),(-100d,100d),(100d,-100d),(-100d,-100d)}){var data=TrackAdjustment.Adjust(original,1.0000001,east,northMeters);Check(Math.Sign(data.Segments[0][0].Longitude)==Math.Sign(east)&&Math.Sign(data.Segments[0][0].Latitude)==Math.Sign(northMeters)&&data.Segments.Count==2,"four-directions-and-100ns-precision");}
  foreach(var option in new[]{(double.NaN,0d,0d),(0d,double.PositiveInfinity,0d),(315576000.1,0d,0d),(-315576000.1,0d,0d),(0d,100000.01,0d),(0d,80000d,80000d)})await Reject(()=>{TrackAdjustment.Adjust(original,option.Item1,option.Item2,option.Item3);return Task.CompletedTask;},"nonfinite-distance-time-boundary-rejected");
  foreach(double seconds in new[]{315576000d,-315576000d})Check(TrackAdjustment.Adjust(original,seconds,0,0).Segments.Count==2,"inclusive-time-boundary");Check(TrackAdjustment.Adjust(original,0,100000,0).Segments.Count==2,"inclusive-distance-boundary");
  await Reject(()=>{TrackAdjustment.Adjust(Make(85),0,1,0);return Task.CompletedTask;},"input-polar-rejected");await Reject(()=>{TrackAdjustment.Adjust(Make(84.99),0,0,100000);return Task.CompletedTask;},"output-polar-rejected");Check(TrackAdjustment.Adjust(Make(85),1,0,0).Segments.Count==2,"time-only-polar-allowed");
  foreach(var time in new[]{DateTimeOffset.MaxValue,DateTimeOffset.MinValue}){var data=new TrackData(new[]{(IReadOnlyList<TrackPoint>)new[]{new TrackPoint(0,0,null,time)}});await Reject(()=>{TrackAdjustment.Adjust(data,time==DateTimeOffset.MaxValue?1:-1,0,0);return Task.CompletedTask;},"year-boundary-rejected");}
  var year=new TrackData(new[]{(IReadOnlyList<TrackPoint>)new[]{new TrackPoint(0,0,0,DateTimeOffset.Parse("2023-12-31T23:59:59.5Z"))}});Check(TrackAdjustment.Adjust(year,1,0,0).Segments[0][0].Time==DateTimeOffset.Parse("2024-01-01T00:00:00.5Z"),"cross-day-year-fraction");
  string source=Path.Combine(folder,"source.gpx");await TrackAdjustment.ExportAsync(original,Path.Combine(folder,"input.kml"),source);var sourceHash=await PhotoDocument.HashAsync(source);var snapshot=await TrackSnapshots.ReadSourceAsync(source);string archive=Path.Combine(folder,"history.json.adjustments-v1.json");
  string legacyArchive=Path.Combine(folder,"legacy-optional.json");File.WriteAllText(legacyArchive,JsonSerializer.Serialize(new{Version=1,Records=new[]{new{snapshot.Path,snapshot.SourceHash,snapshot.Data}}}));Check(TrackSnapshots.Read(legacyArchive).Single().Original is null,"optional-original-absent-is-unadjusted");
  Check(TrackAdjustment.Adjust(original,3600,0,0).Segments[0][1].Time is null,"common-mixed-untimed-case-stays-untimed");
  var first=snapshot with{Data=negative,Original=snapshot.Data};await TrackSnapshots.SaveAsync(archive,first,snapshot);var restart=TrackSnapshots.Read(archive).Single();Check(TrackAdjustment.Equal(restart.Data,negative)&&TrackAdjustment.Equal(restart.Original!,original),"persist-restart-original-effective");
  Check(TrackSnapshots.Read(Path.Combine(folder,"old-no-adjustments.json")).Length==0,"legacy-path-history-no-adjustment");string history=Path.Combine(folder,"recent.json");TrackHistory.Save(history,new[]{source});Check(TrackHistory.Read(history).Single()==Path.GetFullPath(source),"legacy-path-array-compatible");
  var second=first with{Data=TrackAdjustment.Adjust(first.Data,2,10,-10)};await TrackSnapshots.SaveAsync(archive,second,first);await Reject(()=>TrackSnapshots.SaveAsync(archive,first,first),"other-instance-stale-state-rejected");
  string denied=Path.Combine(folder,"not-directory");File.WriteAllText(denied,"keep");await Reject(()=>TrackSnapshots.SaveAsync(Path.Combine(denied,"archive.json"),first,snapshot),"persistence-failure-no-state-change");Check(TrackAdjustment.Equal(TrackSnapshots.Read(archive).Single().Data,second.Data),"previous-persisted-state-kept");
  foreach(string raw in new[]{"{\"Version\":1,\"Records\":[],\"Records\":[]}","{\"Version\":1}","{\"Version\":1,\"Records\":[],\"unknown\":true}"}){string malformed=Path.Combine(folder,"malformed.json");File.WriteAllText(malformed,raw);await Reject(()=>TrackSnapshots.SaveAsync(malformed,first,snapshot),"strict-archive-corruption-rejected");Check(File.ReadAllText(malformed)==raw,"strict-corrupt-archive-preserved");}
  string corrupt=Path.Combine(folder,"corrupt.json");File.WriteAllText(corrupt,"invalid");await Reject(()=>TrackSnapshots.SaveAsync(corrupt,first,snapshot),"corrupt-record-not-overwritten");Check(File.ReadAllText(corrupt)=="invalid","corrupt-content-preserved");
  string exported=Path.Combine(folder,"adjusted.gpx");await TrackAdjustment.ExportAsync(second.Data,source,exported);Check(TrackAdjustment.Equal(TrackReader.ReadGpx(exported),second.Data)&&await PhotoDocument.HashAsync(source)==sourceHash,"export-readback-source-sha");await Reject(()=>TrackAdjustment.ExportAsync(second.Data,source,exported),"occupied-target-rejected");await Reject(()=>TrackAdjustment.ExportAsync(second.Data,source,source),"source-overwrite-rejected");
  using(var cancel=new CancellationTokenSource()){cancel.Cancel();string target=Path.Combine(folder,"cancel.gpx");await Reject(()=>TrackAdjustment.ExportAsync(original,source,target,cancel.Token),"export-cancel");Check(!File.Exists(target)&&!Directory.GetFiles(folder,".track-export-*").Any(),"cancel-no-partial-output");}
  using(var cancel=new CancellationTokenSource()) {
   var large=new TrackData(new[]{(IReadOnlyList<TrackPoint>)Enumerable.Range(0,10000).Select(i=>new TrackPoint(0,i*0.000001,1,DateTimeOffset.UnixEpoch.AddSeconds(i))).ToArray()});string target=Path.Combine(folder,"cancel-after-write.gpx");
   var export=TrackAdjustment.ExportAsync(large,source,target,cancel.Token);bool writing=false;
   for(int i=0;i<1000&&!export.IsCompleted;i++){try{writing=Directory.GetFiles(folder,".track-export-*").Any(p=>new FileInfo(p).Length>0);}catch(FileNotFoundException){}if(writing)break;await Task.Delay(1);}
   Check(writing,"cancel-export-observed-temporary-bytes-written");cancel.Cancel();await Reject(()=>export,"cancel-after-export-write-started");Check(!File.Exists(target)&&!Directory.GetFiles(folder,".track-export-*").Any()&&await PhotoDocument.HashAsync(source)==sourceHash,"mid-export-cancel-cleans-output-and-keeps-source");
  }
  var bytes=File.ReadAllBytes(source);File.AppendAllText(source," ");await Reject(()=>TrackSnapshots.EnsureSourceAsync(second),"external-source-change");await Reject(()=>TrackSnapshots.SaveAsync(archive,first,second),"changed-source-no-new-persistence");File.WriteAllBytes(source,bytes);
  File.Move(source,source+".hold");try{await Reject(()=>TrackSnapshots.EnsureSourceAsync(second),"lost-source-not-matchable");Check(TrackSnapshots.Read(archive).Single().Data.Segments.Count==2,"lost-source-view-snapshot-retained");}finally{File.Move(source+".hold",source);}
  string kml=Path.Combine(folder,"source.kml");File.WriteAllText(kml,"<kml xmlns='http://www.opengis.net/kml/2.2'><Document><Placemark><LineString><coordinates>0,0,5 0.01,0.02,6</coordinates></LineString></Placemark></Document></kml>");var kmlData=TrackReader.Read(kml);await TrackAdjustment.ExportAsync(kmlData,kml,Path.Combine(folder,"kml-export.gpx"));Check(TrackAdjustment.Equal(kmlData,TrackReader.ReadGpx(Path.Combine(folder,"kml-export.gpx"))),"KML-to-GPX");
  string kmz=Path.Combine(folder,"source.kmz");using(var zip=System.IO.Compression.ZipFile.Open(kmz,System.IO.Compression.ZipArchiveMode.Create)){var entry=zip.CreateEntry("doc.kml");using var writer=new StreamWriter(entry.Open());writer.Write(File.ReadAllText(kml));}await TrackAdjustment.ExportAsync(TrackReader.Read(kmz),kmz,Path.Combine(folder,"kmz-export.gpx"));Check(TrackAdjustment.Equal(kmlData,TrackReader.ReadGpx(Path.Combine(folder,"kmz-export.gpx"))),"KMZ-to-GPX");
  File.WriteAllText(Path.Combine(root,"track-common-results.json"),JsonSerializer.Serialize(new{passed,latitudeErrorDegrees=latitudeError,longitudeErrorDegrees=Math.Abs(north.Segments[0][0].Longitude),timeErrorSeconds=timeError,precisionSeconds=0.0000001,sourceHash,exportReadback=true},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("TRACK_ADJUSTMENT_CHECKS="+passed);
 }
}
